-- ========================================================

local ButtonGo = "ActionDreamlandJumpPointNode_Go"
local Select = "ActionDreamlandJumpPointNodeSelect"



-- ========================================================

function UI_JumpHintEntity:__init()
    self.controller = nil
end


function UI_JumpHintEntity:__delete()
    if self.co_1 ~= nil then
        cs_coroutine.stop(self.co_1)
    end
    self.co_1 = nil
end



function UI_JumpHintEntity:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.canvasGroup and self.selectRTF and self.buttonAnimation and self.button )
    self.button.onClick:AddListener( Bind(self, self.OnPress) )
    KTool.SetActive( self.selectRTF.gameObject, false )
end




function UI_JumpHintEntity:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function UI_JumpHintEntity:OnPress() 
    self.buttonAnimation:Play(ButtonGo)

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(function()
        self:Doing()
    end) 
end


function UI_JumpHintEntity:Doing() 
    KTool.SetActive( self.selectRTF.gameObject, true )
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))
    KTool.SetActive( self.selectRTF.gameObject, false )
end




function UI_JumpHintEntity:PlayHide() 
    KTool.SetActive( self.button.gameObject, false )
end



function UI_JumpHintEntity:PlayShow() 
    KTool.SetActive( self.button.gameObject, true )
end



return UI_JumpHintEntity

